import React, { forwardRef, PropsWithChildren } from 'react';

import { extractSlots } from './functions/extract-slots.js';
import { Chart } from './slots/Chart.js';
import { Icon } from './slots/Icon.js';
import { Label } from './slots/Label.js';
import { Legend } from './slots/Legend.js';
import { Max } from './slots/Max.js';
import { Min } from './slots/Min.js';
import { Value } from './slots/Value.js';
import {
  StyledValue,
  StyledMin,
  StyledMax,
  StyledLegend,
  StyledLabel,
  StyledChart,
} from './types/styles.js';
import type { StylingProps } from '../../../../../core/types/styling-props.js';
import { Grid } from '../../../../../layouts-core/grid/Grid.js';
import { MeterBarLayoutSizeContext } from '../../context/MeterBarLayoutSize.context.js';
import { MeterBarSize } from '../../types/meter-bars.js';

export interface MeterBarLayoutProps extends StylingProps {
  /**
   * The size that applies to the value, icon, and label.
   * @defaultvalue 'size16'
   */
  size: MeterBarSize;
}

/**
 * Component responsible for defining the layout of the meter bars.
 * The layout is divided in the labels area (icon, label and value), chart area and legend area.
 */
export const MeterBarLayoutRoot = forwardRef<
  HTMLDivElement,
  PropsWithChildren<MeterBarLayoutProps>
>(({ size, children, className, style }, forwardedRef) => {
  const { label, min, max, value, chart, icon, legend } =
    extractSlots(children);

  return (
    <div>
      <Grid
        ref={forwardedRef}
        gridTemplateAreas="
          'label label label value'
          'chart chart chart chart'
          'min min max max'
          'legend legend legend legend'"
        gridTemplateColumns="25% 25% 25% 25%"
        gridTemplateRows="auto"
        rowGap={0}
        columnGap={0}
        className={className}
        style={style}
        data-testid="meter-bar-container"
      >
        <MeterBarLayoutSizeContext.Provider value={{ size }}>
          {(label || icon) && (
            <StyledLabel>
              {icon && icon}
              {label && label}
            </StyledLabel>
          )}
          {value && <StyledValue>{value}</StyledValue>}
          <StyledChart>{chart}</StyledChart>
          {min && <StyledMin $size={size}>{min}</StyledMin>}
          {max && <StyledMax $size={size}>{max}</StyledMax>}
          {legend && <StyledLegend>{legend}</StyledLegend>}
        </MeterBarLayoutSizeContext.Provider>
      </Grid>
    </div>
  );
});

MeterBarLayoutRoot['displayName'] = 'MeterBarLayoutRoot';

/** Slot component for meter bar */
export const MeterBarLayout = Object.assign(MeterBarLayoutRoot, {
  Label,
  Min,
  Max,
  Chart,
  Value,
  Icon,
  Legend,
});
